[InitializeOnLoad]public static class RiftAchievementStandaloneReview {
 const string ReviewKey="ROM.AchievementStandalone";static readonly string[] SavedKeys={"ROM.Character.ActiveId",AbilityController.Preference,PlayerInstance.ClassPreference,"_playerPrefs_Username","_playerPrefs_CharacterSkinID",RiftControls.Preference};
 static string Output=>Path.GetFullPath("Logs/AchievementStandalone");static readonly List<string> results=new List<string>();static int step;static double began,next;static Keyboard compactKeyboard;static Mouse compactMouse;static bool compactActive,hadBindings;static int savedBackground,savedEditorInput;static string savedBindings,journalBeforeAchievement;static RiftEditorReviewCapture achievementCapture;
 static RiftAchievementStandaloneReview(){EditorApplication.playModeStateChanged+=Changed;}
 public static void Run(){if(SessionState.GetBool(ReviewKey,false))return;for(int i=0;i<UnityEngine.SceneManagement.SceneManager.sceneCount;i++)if(UnityEngine.SceneManagement.SceneManager.GetSceneAt(i).isDirty)throw new Exception("Refusing test while scene has unsaved changes");foreach(string k in SavedKeys){SessionState.SetBool(ReviewKey+k+"Exists",PlayerPrefs.HasKey(k));SessionState.SetString(ReviewKey+k,IsInt(k)?PlayerPrefs.GetInt(k).ToString():PlayerPrefs.GetString(k));}SessionState.SetString(ReviewKey+"Nickname",UserSettings.UserNickname);SessionState.SetInt(ReviewKey+"Skin",UserSettings.CharacterSkinID);SessionState.SetBool(ReviewKey,true);Directory.CreateDirectory(Output);SessionState.SetString(ReviewKey+"SceneHash",MapSourceHash());EditorSceneManager.OpenScene("Assets/ROM/Scenes/MainMenu.unity");EditorApplication.isPlaying=true;}
 static bool IsInt(string k)=>k==AbilityController.Preference||k==PlayerInstance.ClassPreference||k=="_playerPrefs_CharacterSkinID";
 static void Changed(PlayModeStateChange state){if(!SessionState.GetBool(ReviewKey,false))return;if(state==PlayModeStateChange.EnteredPlayMode){step=0;began=next=EditorApplication.timeSinceStartup;EditorApplication.update+=Tick;}if(state==PlayModeStateChange.EnteredEditMode){SessionState.SetBool(ReviewKey,false);foreach(var k in SavedKeys){if(!SessionState.GetBool(ReviewKey+k+"Exists",false))PlayerPrefs.DeleteKey(k);else if(IsInt(k))PlayerPrefs.SetInt(k,int.Parse(SessionState.GetString(ReviewKey+k,"0")));else PlayerPrefs.SetString(k,SessionState.GetString(ReviewKey+k,""));}UserSettings.UserNickname=SessionState.GetString(ReviewKey+"Nickname","");UserSettings.CharacterSkinID=SessionState.GetInt(ReviewKey+"Skin",1);PlayerPrefs.Save();EditorApplication.Exit(SessionState.GetInt(ReviewKey+"Result",1));}}
 static void Tick(){try{if(EditorApplication.timeSinceStartup-began>180)throw new Exception("Timeout at step "+step);if(EditorApplication.timeSinceStartup<next)return;
 if(step==0){var menu=UnityEngine.Object.FindFirstObjectByType<RiftHub>();if(!menu||!menu.Stage||!menu.Stage.Ready)return;var account="AchievementReview_"+Guid.NewGuid().ToString("N");var social=new LocalSocialState{ActiveId=account,LeaderId=account,Profiles=new List<LocalFriend>{new LocalFriend{Id=account,Name=account,Skin=1}},Party=new List<LocalPartyMember>{new LocalPartyMember{ProfileId=account}}};var file=Path.Combine(Output,account+".json");File.WriteAllText(file,JsonUtility.ToJson(social));menu.UseLocalService(new LocalSocialService(file));var roster=new LocalCharacterRoster(account,RiftSkinIdentity.Name(1),1,"warrior");typeof(RiftHub).GetField("roster",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(menu,roster);typeof(RiftHub).GetField("rosterAccount",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(menu,account);menu.ApplyActiveCharacter();RiftJournalPlayer.StorageOverride=Path.Combine(Output,"isolated-journals");menu.Creator.BotsToggle.isOn=false;menu.Deploy();menu.GetComponentsInChildren<Button>(true).First(b=>b.gameObject.activeInHierarchy&&b.GetComponentInChildren<Text>()?.text=="CONFIRMAR").onClick.Invoke();Advance(17);return;}
 if(step==1){var player=ClientFrontend.ClientPlayerInstance;if(!player||!player.MyCharacter)return;Check(player.MyCharacter.GetComponent<WarriorAvatar>(),"Real menu deploy creates Warrior actor");Check(player.PlayerInfo.Warrior,"Server accepts native Warrior identity");Advance();return;}TickCore();
 }catch(Exception e){results.Add("FAIL "+e);Finish(false);}}
 static void Check(bool condition,string text){if(!condition)throw new Exception(text);results.Add("PASS "+text);}
 static void Advance(double delay=1){step++;next=EditorApplication.timeSinceStartup+delay;}
 static void TapCompact(UnityEngine.InputSystem.Key key)=>InputSystem.QueueStateEvent(compactKeyboard,new KeyboardState(key));static void Release()=>InputSystem.QueueStateEvent(compactKeyboard,new KeyboardState());
 static void At(Transform target,ushort buttons=0){Canvas.ForceUpdateCanvases();var rect=(RectTransform)target;var point=RectTransformUtility.WorldToScreenPoint(null,rect.TransformPoint(rect.rect.center));InputSystem.QueueStateEvent(compactMouse,new MouseState{position=point,buttons=buttons});}
 static void AchievementShot(string name){achievementCapture=new RiftEditorReviewCapture();achievementCapture.Save(Path.Combine(Output,name+".png"),RiftVideoSettings.Instance);}
 static bool AchievementSaved(){if(achievementCapture==null||!achievementCapture.Done)return false;if(achievementCapture.Error!=null)throw achievementCapture.Error;return true;}
 static void Finish(bool pass){EditorApplication.update-=Tick;foreach(var pair in reviewDevices)if(pair.Key)pair.Key.devices=pair.Value;reviewDevices.Clear();if(compactActive){if(compactKeyboard!=null)InputSystem.RemoveDevice(compactKeyboard);if(compactMouse!=null)InputSystem.RemoveDevice(compactMouse);if(hadBindings)PlayerPrefs.SetString(RiftControls.Preference,savedBindings);else PlayerPrefs.DeleteKey(RiftControls.Preference);RiftControls.Reload();InputSystem.settings.backgroundBehavior=(InputSettings.BackgroundBehavior)savedBackground;InputSystem.settings.editorInputBehaviorInPlayMode=(InputSettings.EditorInputBehaviorInPlayMode)savedEditorInput;compactActive=false;}File.WriteAllLines(Path.Combine(Output,"validation.txt"),results);SessionState.SetInt(ReviewKey+"Result",pass?0:1);if(NetworkServer.active)NetworkManager.singleton.StopHost();EditorApplication.isPlaying=false;}
 static Vector2 mapPanStart,mapPointer;static string MapSourceHash(){using(var file=File.OpenRead("Assets/ROM/Levels/map_rom_horde.unity"))using(var hash=System.Security.Cryptography.SHA256.Create())return BitConverter.ToString(hash.ComputeHash(file));}
 static void MapTick(){var map=UnityEngine.Object.FindFirstObjectByType<RiftFieldUI>();var actor=ClientFrontend.ClientPlayerInstance.MyCharacter;
 if(step>=29){CartographyLiveTick(map);return;}
 if(step==17){Check(map,"Map UI exists in actual El Rift");RiftControls.Bind("WorldMap",0,"<Keyboard>/m");At(map.MapButton.transform,1);Advance(.3);return;}
 if(step==18){At(map.MapButton.transform);Advance();return;}
 if(step==19){Check(map.MapOpen&&!ClientFrontend.Pause,"Map button opens world map without pause menu");var atlas=Resources.Load<RiftMinimapAtlas>("RiftMinimapAtlas");Check(map.MapImage.texture==(map.Projection!=null?map.Projection.Texture:atlas.Map),"M uses calibrated illustration or exact literal fallback");Check(Mathf.Abs(atlas.Center.x-103.759705f)<.0001f&&Mathf.Abs(atlas.Center.y+9.095184f)<.0001f,"Atlas center preserved");Check(Vector2.Distance(atlas.WorldSize,new Vector2(2027.8888f,2027.8888f))<.0001f,"Atlas world bounds preserved");var points=UnityEngine.Object.FindObjectsByType<ROM.Horde.RiftCheckpoint>(FindObjectsSortMode.None);Check(points.Length==7&&points.Count(c=>c.StartingCamp)==1,"Seven actual checkpoints and one starting camp");foreach(var point in points){var pin=map.Content.Find(point.Title) as RectTransform;Check(pin&&Vector2.Distance(pin.anchoredPosition,map.Position(point.transform.position))<.001f,"World marker aligns: "+point.Title);}Check(map.Position(actor.transform.position+Vector3.right).x>map.Position(actor.transform.position).x&&map.Position(actor.transform.position+Vector3.forward).y>map.Position(actor.transform.position).y,"Map orientation +X right and +Z up");Check(Vector2.Distance(map.PlayerMarker.anchoredPosition,map.Position(actor.transform.position))<.001f,"Player marker follows actual actor position");Check(!UICursorManager.GamePlayInput(),"Map holds interface cursor input");var hudGroup=UnityEngine.Object.FindFirstObjectByType<RiftGameplayHUD>().GetComponent<CanvasGroup>();Check(hudGroup&&hudGroup.alpha==0&&!hudGroup.blocksRaycasts,"Map hides gameplay HUD without covering the world");RiftAbilityTooltip.HideAll();AchievementShot("rift-map-integrated");Advance();return;}
 if(step==20){if(!AchievementSaved())return;var rect=map.Viewport;mapPointer=RectTransformUtility.WorldToScreenPoint(null,rect.TransformPoint(rect.rect.center));InputSystem.QueueStateEvent(compactMouse,new MouseState{position=mapPointer,scroll=new Vector2(0,120)});Advance();return;}
 if(step==21){Check(map.Content.localScale.x>1&&map.Content.localScale.x<=4,"Mouse wheel zooms map through live input");map.SetZoom(99);Check(map.Content.localScale.x==4,"Map zoom upper bound clamps to four");map.SetZoom(.1f);Check(map.Content.localScale.x==1,"Map zoom lower bound clamps to one");map.SetZoom(2);mapPanStart=map.Content.anchoredPosition;InputSystem.QueueStateEvent(compactMouse,new MouseState{position=mapPointer,buttons=1});Advance(.3);return;}
 if(step==22){InputSystem.QueueStateEvent(compactMouse,new MouseState{position=mapPointer+new Vector2(130,85),buttons=1});Advance(.3);return;}
 if(step==23){InputSystem.QueueStateEvent(compactMouse,new MouseState{position=mapPointer+new Vector2(260,160),buttons=1});Advance();return;}
 if(step==24){results.Add("INFO drag start="+mapPanStart+" end="+map.Content.anchoredPosition+" mouse="+compactMouse.position.ReadValue()+" module="+EventSystem.current.currentInputModule);Check(Vector2.Distance(map.Content.anchoredPosition,mapPanStart)>20,"Drag pans zoomed map through ScrollRect");InputSystem.QueueStateEvent(compactMouse,new MouseState{position=mapPointer+new Vector2(260,160)});RiftAbilityTooltip.HideAll();AchievementShot("rift-map-zoom-pan");Advance();return;}
 if(step==25){if(!AchievementSaved())return;TapCompact(UnityEngine.InputSystem.Key.Escape);Advance();return;}
 if(step==26){Check(!map.MapOpen&&!ClientFrontend.Pause,"Escape closes only map layer");Check(UICursorManager.GamePlayInput(),"Map close releases interface input");Release();TapCompact(UnityEngine.InputSystem.Key.M);Advance();return;}
 if(step==27){Check(map.MapOpen,"M binding reopens world map");Release();map.CloseButton.onClick.Invoke();Advance();return;}
 if(step==28){Check(!map.MapOpen,"Map close button returns to gameplay");Check(SessionState.GetString(ReviewKey+"SceneHash","")==MapSourceHash(),"Source geography unchanged by all Editor tests");ModernMapChecks(map);if(map.Projection!=null){RiftCartographyReview.Start(map);AchievementShot("rift-map-illustrated-traces");Advance(.5);return;}Finish(true);}
 }
 static void ModernMapChecks(RiftFieldUI map){
  var frame=map.GetComponent<RiftModernMapFrame>();Check(frame,"Map-only modern frame installed");map.SetMap(true);Canvas.ForceUpdateCanvases();
  if(map.Projection!=null)foreach(var result in RiftCartographyReview.Validate(map))results.Add("PASS "+result);Check(!map.MapPanel.GetComponent<RiftHUDGraphic>().enabled,"Legacy gold map border disabled locally");
  Check(map.Viewport.rect.width>map.Viewport.rect.height,"Modern map has spacious viewport beside navigation");
  var checkpoint=map.Content.Cast<Transform>().First(t=>t.GetComponent<RiftTooltipTrigger>()?.Description=="Cristal / refugio");
  var encounter=map.Content.Cast<Transform>().First(t=>t.GetComponent<RiftTooltipTrigger>()?.Description=="Zona de encuentro");
  var filter=map.MapPanel.GetComponentsInChildren<Button>().First(b=>b.name=="Filter checkpoints");filter.onClick.Invoke();Check(!checkpoint.gameObject.activeSelf&&encounter.gameObject.activeSelf,"Checkpoint filter only hides actual checkpoint pins");filter.onClick.Invoke();Check(checkpoint.gameObject.activeSelf,"Checkpoint filter restores pins");
  filter=map.MapPanel.GetComponentsInChildren<Button>().First(b=>b.name=="Filter encounters");filter.onClick.Invoke();Check(!encounter.gameObject.activeSelf&&checkpoint.gameObject.activeSelf,"Encounter filter independently hides actual encounter pins");filter.onClick.Invoke();
  var atlas=Resources.Load<RiftMinimapAtlas>("RiftMinimapAtlas");foreach(var p in UnityEngine.Object.FindObjectsByType<ROM.Horde.RiftCheckpoint>(FindObjectsSortMode.None)){var q=map.Position(p.transform.position);Check(map.TryWorldPosition(q,out var back)&&Vector2.Distance(new Vector2(back.x,back.z),new Vector2(p.transform.position.x,p.transform.position.z))<.04f,"World-map bidirectional round trip: "+p.Title);}
  map.SetZoom(2);map.Content.anchoredPosition=new Vector2(70,90);frame.Recenter();var actor=ClientFrontend.ClientPlayerInstance.MyCharacter;Check(Vector2.Distance(map.Content.anchoredPosition,-map.Position(actor.transform.position)*2)<.001f,"Recenter uses actual local player and current zoom");
  for(int i=0;i<3;i++){map.SetMap(false);map.SetMap(true);}Check(map.MapOpen&&!ClientFrontend.Pause,"Repeated map reopen remains on one UI layer");map.SetMap(false);Check(UICursorManager.GamePlayInput(),"Repeated map close releases cursor");
 }
 static void CartographyLiveTick(RiftFieldUI map){
  if(step==29){if(!AchievementSaved())return;if(RiftCartographyReview.LiveStep()){next=EditorApplication.timeSinceStartup+.2;return;}Check(true,"63 live server-actor traversal samples across all nine bridges follow map position and projected heading");At(map.Content,1);Advance(.3);return;}
  if(step==30){At(map.Content);Advance();return;}
  if(step==31){Check(map.MapInfo.text.StartsWith("Ubicación del mapa"),"Mouse map click uses calibrated inverse coordinates without teleport");var filter=map.MapPanel.GetComponentsInChildren<Button>().First(b=>b.name=="Filter encounters");EventSystem.current.SetSelectedGameObject(filter.gameObject);TapCompact(UnityEngine.InputSystem.Key.Enter);Advance();return;}
  if(step==32){Release();var encounter=map.Content.Cast<Transform>().First(t=>t.GetComponent<RiftTooltipTrigger>()?.Description=="Zona de encuentro");Check(!encounter.gameObject.activeSelf,"Keyboard submit toggles selected actual map filter");TapCompact(UnityEngine.InputSystem.Key.Escape);Advance();return;}
  if(step==33){Release();Check(!map.MapOpen&&map.MapButton.gameObject.activeSelf,"Escape restores normal MAPA control");var group=UnityEngine.Object.FindFirstObjectByType<RiftGameplayHUD>().GetComponent<CanvasGroup>();Check(!group||group.alpha>0,"Closing full map restores normal gameplay HUD");Finish(true);}
 }
 static readonly Dictionary<InputActionAsset,InputDevice[]> reviewDevices=new Dictionary<InputActionAsset,InputDevice[]>();
 static void IsolateUIInput(){foreach(var module in UnityEngine.Object.FindObjectsByType<UnityEngine.InputSystem.UI.InputSystemUIInputModule>(FindObjectsSortMode.None)){var asset=module.actionsAsset;if(!asset||reviewDevices.ContainsKey(asset))continue;reviewDevices[asset]=asset.devices.HasValue?asset.devices.Value.ToArray():null;asset.devices=new InputDevice[]{compactKeyboard,compactMouse};}}
 static bool overviewRestored;
 static void AuditIconSizes(RiftAchievementView view,bool small){foreach(var image in view.GetComponentsInChildren<RawImage>()){if(!image.name.StartsWith("Achievement art "))continue;var rect=image.rectTransform;float old=rect.sizeDelta.x,desired=small?(old>100?110:58):(old>100?156:76);float delta=(old-desired)*.5f;rect.anchoredPosition+=new Vector2(delta,-delta);rect.sizeDelta=Vector2.one*desired;}}
 static void TickCore(){if(step>=17){MapTick();return;}var player=ClientFrontend.ClientPlayerInstance;if(!player||!player.MyCharacter)return;var pause=UIPauseMenu._instance;var hub=pause.pauseMenuOverlay.GetComponentInChildren<RiftHub>(true);var view=hub.GetComponentInChildren<RiftAchievementView>(true);
 if(step==2){EditorApplication.ExecuteMenuItem("Window/General/Game");compactActive=true;savedBackground=(int)InputSystem.settings.backgroundBehavior;savedEditorInput=(int)InputSystem.settings.editorInputBehaviorInPlayMode;InputSystem.settings.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;InputSystem.settings.editorInputBehaviorInPlayMode=InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;hadBindings=PlayerPrefs.HasKey(RiftControls.Preference);savedBindings=PlayerPrefs.GetString(RiftControls.Preference,"");compactKeyboard=InputSystem.AddDevice<Keyboard>();compactKeyboard.MakeCurrent();compactMouse=InputSystem.AddDevice<Mouse>();compactMouse.MakeCurrent();IsolateUIInput();RiftControls.Bind("Achievements",0,"<Keyboard>/f7");journalBeforeAchievement=JsonUtility.ToJson(RiftJournalView.Read());if(Environment.GetCommandLineArgs().Contains("-riftMapOnlyReview")){step=17;next=EditorApplication.timeSinceStartup+.3;return;}TapCompact(UnityEngine.InputSystem.Key.F7);Advance(2);return;}
 if(step==3){Release();Check(ClientFrontend.Pause&&hub.Page==HubPage.Progression&&view,"Achievement binding opens new screen after real Warrior entry");Check(view.VisibleCount==7,"All seven actual catalog achievements displayed");Check(RiftJournalCatalog.Load.Achievements.Sum(a=>a.Points)==100,"Actual catalog keeps 100 total achievement points");var card=view.GetComponentsInChildren<RiftAchievementRow>().First();var definition=RiftJournalCatalog.Load.Achievements.First(a=>a.Id==card.Id);var title=card.GetComponentsInChildren<Text>().First(t=>t.text==definition.Title).rectTransform;var status=card.GetComponentsInChildren<Text>().First(t=>t.text=="Sin iniciar").rectTransform;Check(-title.anchoredPosition.y+title.rect.height<=-status.anchoredPosition.y,"Card title and status occupy separate vertical lanes");var list=card.transform.parent as RectTransform;Check(view.GetComponentsInChildren<RiftAchievementRow>().Count(r=>-((RectTransform)r.transform).anchoredPosition.y+((RectTransform)r.transform).rect.height<=580)==4,"Four full achievement cards fit the viewport");Check(view.Preview.Ready&&view.Preview.SourceCharacter==player.MyCharacter,"Achievement preview uses actual local actor");if(Environment.GetCommandLineArgs().Contains("-riftAchievementIconSizeReview")){var art=view.GetComponentsInChildren<RawImage>().Where(i=>i.name.StartsWith("Achievement art ")).ToArray();Check(art.Select(i=>i.name).Distinct().Count()==7,"Seven stable IDs resolve to candidate atlas cells");Check(art.All(i=>i.uvRect.width<.25f&&i.uvRect.height<.5f),"Atlas UVs have explicit inset against adjacent-cell bleed");AuditIconSizes(view,true);AchievementShot("rift-achievements-icons58-110");}else AchievementShot("rift-achievements-all");Advance();return;}
 if(step==4){if(!AchievementSaved())return;if(Environment.GetCommandLineArgs().Contains("-riftAchievementIconSizeReview")&&!overviewRestored){AuditIconSizes(view,false);overviewRestored=true;AchievementShot("rift-achievements-all");return;}var button=view.GetComponentsInChildren<Button>().First(b=>b.name=="Achievement category Combate");At(button.transform,1);Advance(.3);return;}
 if(step==5){At(view.GetComponentsInChildren<Button>().First(b=>b.name=="Achievement category Combate").transform);Advance();return;}
 if(step==6){Check(view.Filter=="Combate"&&view.VisibleCount==4,"Mouse click filters actual combat criteria");var row=view.GetComponentsInChildren<RiftAchievementRow>().Last();EventSystem.current.SetSelectedGameObject(row.gameObject);Advance();return;}
 if(step==7){Check(view.Selected==view.GetComponentsInChildren<RiftAchievementRow>().Last().Id,"Keyboard focus updates selected achievement detail");TapCompact(UnityEngine.InputSystem.Key.Enter);Advance();return;}
 if(step==8){Release();At(view.GetComponentsInChildren<RiftAchievementRow>().Last().transform);Advance();return;}
 if(step==9){Check(RiftAbilityTooltip.Current&&RiftAbilityTooltip.Current.Visible,"Hover displays real achievement description tooltip");AchievementShot("rift-achievements-combat-tooltip");Advance();return;}
 if(step==10){if(!AchievementSaved())return;Check(JsonUtility.ToJson(RiftJournalView.Read())==journalBeforeAchievement,"Selection filter tooltip and submit do not mutate journal or rewards");var all=view.GetComponentsInChildren<Button>().First(b=>b.name=="Achievement category Todos");all.onClick.Invoke();Advance();return;}
 if(step==11){var rows=view.GetComponentsInChildren<RiftAchievementRow>();EventSystem.current.SetSelectedGameObject(rows.Last().gameObject);Advance();return;}
 if(step==12){Check(view.GetComponentInChildren<ScrollRect>().content.anchoredPosition.y>0,"Keyboard selection scrolls last real card into view");RiftAbilityTooltip.HideAll();AchievementShot("rift-achievements-last-selected");Advance();return;}
 if(step==13){if(!AchievementSaved())return;TapCompact(UnityEngine.InputSystem.Key.Escape);Advance();return;}
 if(step==14){Check(!ClientFrontend.Pause,"Escape closes achievements without opening another panel");Release();TapCompact(UnityEngine.InputSystem.Key.F7);Advance();return;}
 if(step==15){Release();Check(ClientFrontend.Pause&&hub.Page==HubPage.Progression,"Achievement binding reopens screen");view=hub.GetComponentInChildren<RiftAchievementView>();view.GetComponentsInChildren<Button>().First(b=>b.name=="Close achievements").onClick.Invoke();Advance();return;}
 if(step==16){Check(!ClientFrontend.Pause,"Close button returns to gameplay");Check(JsonUtility.ToJson(RiftJournalView.Read())==journalBeforeAchievement,"Reopen and close preserve exact original journal state");if(Environment.GetCommandLineArgs().Contains("-riftMapIntegrationReview")){Advance();return;}Finish(true);}
 }
